from typing import List, Tuple

class GiftShop:
    def __init__(self, n: int, m: int, gift_prices: List[Tuple[int, List[int]]]):
        self.gifts = gift_prices
        self.name_to_count: dict[str, Tuple[int, int]] = {}
        for i in range(n):
            name, count, prices = self.gifts[i]
            if name not in self.name_to_count:
                self.name_to_count[name] = (count, len(prices))
            else:
                self.name_to_count[name] = (count, max(self.name_to_count[name][1], len(prices)))

    def get_gifts(self, i: int) -> List[Tuple[int, int]]:
        gifts = []
        name, count, prices = self.name_to_count[list(self.name_to_count.keys())[i]]
        while count > 0:
            max_price_index = bisect.bisect_left(prices, count)
            if max_price_index < len(prices):
                max_price = prices[max_price_index]
            else:
                max_price = prices[-1]
            gifts.append((i + 1, max_price))
            prices.remove(max_price)
            count -= max_price
        return gifts

def calculate_probability(gifts: List[Tuple[int, int]]) -> float:
    prob = 1.0
    for i in range(len(gifts)):
        gift_count = len(gifts[i])
        at_most_gift_count = min(gifts.count(gifts[i]), gift_count)
        prob *= (at_most_gift_count / gift_count) ** at_most_gift_count
    return prob

if __name__ == "__main__":
