from collections import Counter

def mex_values(subarray):
    subarray_count = Counter(subarray)
    mex = 0
    used = set()
    for value, count in subarray_count.items():
        if value in used:
            continue
        mex = value
        used.add(value)
        for i in range(value+1, value+2):
            if i not in used and i in subarray_count:
                used.add(i)
                mex = i
                break
    return mex

def count_valid_pairs(N, P):
    mexes = [mex_values(subarray) for subarray in [P[i:i+2] for i in range(N-1)]]
    count = 0
    for i in range(N-1):
        for j in range(i+1, N):
            if mexes[i] == mexes[j]:
                count += 1
    return count

