from itertools import permutations

def is_mex_fixed(p, L, R):
    original_perm = list(p)
    original_perm[L], original_perm[R] = original_perm[R], original_perm[L]
    new_perm = list(map(str, original_perm))
    new_perm[L-1], new_perm[R-1] = new_perm[R-1], new_perm[L-1]
    new_perm = ''.join(new_perm)
    return new_perm == max(new_perm)

def count_valid_pairs(N, p):
    valid_pairs = 0
    for L in range(N):
        for R in range(L+1, N+1):
            if is_mex_fixed(p, L, R):
                valid_pairs += 1
    return valid_pairs

