class HorcruxEngine:
    def __init__(self):
        self.information = []

    def add_snake(self, l, r, k):
        bisect.insort(self.information, (k, l, r))
        return self.information

    def calculate_danger(self, l, r):
        danger = 0
        for (slope, left, right) in self.information:
            if l <= left < right <= r:
                if slope > 0:
                    danger += slope
                else:
                    danger -= abs(slope)
