from typing import List
from collections import deque

def maxCrossQuery(s: str, l: int, r: int) -> int:
    """ Compute the Z-function and the sum of Z-function. """
    n = len(s)
    z = [0] * n
    left = right = 0

    for i in range(1, n):
        if i <= right - left:
            z[i] = min(right - left, z[i - left])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > right + 1:
            left, right = i, i + z[i] - 1

    sum_z = sum(z)

    return (1 + sum_z) * (n - right)

