from math import sqrt

def bellman_ford(G, s):
    """Bellman-Ford algorithm to compute shortest paths in a graph with non-negative edge weights."""
    dist = {v: float('inf') for v in G}
    dist[s] = 0
    for _ in range(len(G) - 1):
        for u, v, w in G:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    return dist

def compute_prob(G, a, b, c, d):
    """Compute the probability of existence of an lr-circulation in the graph with random t in [0, 1]."""
    G_t = [[[], []] for _ in range(len(G))]
    h_t = lambda t: a * t + b
    ln_t = lambda t: c * t + d

    for u, v, a_e, b_e, c_e, d_e in G:
        a, b = ln_t(h_t(u) * c_e * c_e - h_t(u) * 128)
        c, d = ln_t(h_t(v) - h_t(v) * b_e)
        if a < 0:
            a, b = min(b, 0.0), max(0.0, b - a)
        c, d = min(-c, 0.0), max(0.0, -c - d)

        if a != b:
            for x in bellman_ford(G_t[v], v):
                G_t[v][x][2] = max(G_t[v][x][2], a)
                G_t[v][x][1] = max(G_t[v][x][1], b)
        for x in bellman_ford(G_t[u], u):
            G_t[u][v][2] = min(G_t[u][v][2], a)
            G_t[u][v][1] = min(G_t[u][v][1], b)

    e = 0.0
    for x, y, w in G_t[v]:
        if x <= y:
            e = max(e, w)
        else:
            if x < 0 and G_t[u][y][1] >= 0:
                e = max(e, -G_t[u][y][1])
        if y <= x:
            e = max(e, w)
        else:
            if y > 0 and G_t[v][x][1] <= 0:
                e = max(e, G_t[v][x][1])

    if e == t:
        return 0.0

    return 1.0 / sqrt(2 * (1 - (t - e)**4))

