import heapq

class DangerousPath:
    def __init__(self, N, ks):
        self.N = N
        self.ks = ks
        self.priority_queue = []

    def update_danger(self, k, l, r, y1, y2):
        heapq.heappush(self.priority_queue, (k, y1, y2, l, r))
        heapq.heappush(self.priority_queue, (10**10, float('inf'), -float('inf'), l, r))

    def query_nagini(self, l, r):
        danger_value = sum(y for k, y1, y2, l, r in self.priority_queue if l <= self.find_k(k, l, r) <= r and self.find_y1(y1) > 0 and self.find_y2(y2) < 0)
        self.check_k_parity(k, danger_value)
        return danger_value

    def check_k_parity(self, k, danger_value):
        if k % 2 != 0 and danger_value > 0:
            danger_value *= -1

    def find_k(self, k, l, r):
        while self.priority_queue and (r < self.priority_queue[0][2] or (self.priority_queue[0][2] == 10**10 and r < self.priority_queue[0][3])):
            k, y1, y2, l, r = heapq.heappop(self.priority_queue)
            if r > l:
                k, y1, y2, l, r = k, y2, -y1, l, r
        return k

    def find_y1(self, y1):
        while self.priority_queue and (y1 < self.priority_queue[0][1] or self.priority_queue[0][1] <= 0):
            k, y1, y2, l, r = heapq.heappop(self.priority_queue)
            if self.priority_queue[0][1] == float('-inf'):
                if l - y1 >= 0:
                    y1 = None
                return y1
        return y1

    def find_y2(self, y2):
        while self.priority_queue and (y2 > self.priority_queue[0][2] or self.priority_queue[0][2] >= 0):
            k, y1, y2, l, r = heapq.heappop(self.priority_queue)
            if self.priority_queue[0][2] == 10**10:
                if abs(y2) * -1 <= abs(r - l):
                    y2 = None
                return y2
        return y2

    def process_queries(self, queries):
        for query in queries:
            if query[0] == 1:
                self.update_danger(*query[1:])
            else:
                print(self.query_nagini(*query[1:]))

def main():
    q = int(input())
    queries = [list(map(int, input().split())) for _ in range(q)]
    dp = DangerousPath(10**5, set())
    dp.process_queries(queries)

if __name__ == "__main__":
