import sys
sys.setrecursionlimit(10**6)

def solve(n, field1, field2, pattern):
    if n == 0:
        return 1
    if n == 1:
        if pattern == field1 or pattern == field2:
            return 2
        return 0
    count = 0
    for i in range(n):
        if pattern[-1] == field1[i]:
            count += solve(n-1, field1[:i] + field2[i:] + field1[i:], field2, pattern[:-1])
            count %= 1000000007
        if pattern[-1] == field2[i]:
            count += solve(n-1, field1[i:] + field2[i:] + field1[i:], field1, pattern[:-1])
            count %= 1000000007
    return count

