            if last_y < l:
                idx = bisect_right(self.y1s, l) - 1
            else:
                idx = bisect_left(self.y1s, l)
            self.y1s.insert(idx, l - 1)

            if last_y > k:
                idx = bisect_right(self.y1s, r) - 1
            else:
