from collections import defaultdict

def count_solutions(field1, field2, word):
    mod = 10**9 + 7
    dp = defaultdict(int)
    dp[(0, 0)] = 1

    for letter, length in zip(field1 + field2, [len(line) for line in [field1, field2]]):
        new_dp = defaultdict(int)
        for x, y in dp.items():
            for prev_x, prev_y in dp.items():
                dx, dy = x[0] - prev_x[0] + length - 1, x[1] - prev_x[1]
                if 0 <= dx < length and 0 <= dy < length:
                    new_val = (y * (word[letter] == field1[prev_x[0]][prev_x[1]])) % mod
                    new_dp[tuple((dx, dy))] += new_val
                    if x[0] == dx and x[1] > dy:
                        new_dp[tuple((prev_x[0], dy))] += (word[letter] == field1[prev_x[0]][prev_x[1]]) * mod
                    if x[0] == x[0] - prev_y[1] + length + 1:
                        new_dp[tuple((dx, prev_x[1] - dy))] += (word[letter] == field1[prev_x[0]][prev_x[1]]) * mod
                if 0 <= dx < length:
                    new_dp[tuple((prev_x[0] + dx, prev_x[1]))] += (word[letter] == field1[prev_x[0]][prev_x[1]]) * mod
            for dx in range(length):
                for dy in range(length):
                    new_dp[tuple((dx, dy))] += (word[letter] == field1[x[0] + dx][x[1] + dy]) * (x[0] - 1) * y % mod
        dp = new_dp

    return sum(dp.values()) % mod

