import math

def max_prob(n, m, gifts):
    total_gifts = {}
    for i in range(1, m + 1):
        k, prices = gifts[i - 1]
        for price in prices:
            if price in total_gifts:
                total_gifts[price].append((i - 1, k))
            else:
                total_gifts[price] = [(i - 1, k)]

    max_gifts_count = 0
    for price, gift_indices in total_gifts.items():
        if len(gift_indices) == n:
            max_gifts_count += 1

    probability = 1.0
    for price, gift_indices in sorted(total_gifts.items(), key=lambda x: x[1], reverse=True):
        proportion = min(n, len(gift_indices))
        for j in range(proportion, 0, -1):
            for gift in gift_indices[:j]:
                price_freq, gift_count = gift_indices[j-1]
                gift_pairs = gift_count // price_freq
                probability = probability * (price / (price + 1)) ** (gift_pairs - 1)
                if gift_pairs > 1:
                    probability *= (gift_count - gift_pairs * price_freq) / (price + 1)
    return probability / math.factorial(n)

