from typing import List
from bisect import insort
from math import inf

# Class to handle segment tree operations
class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [[0] * 4 for _ in range(4 * n)]
        self.log = [0] + [0] * 68
        self.nown = [0] * 68

    def _build(self, i, b, e):
        if b == e:
            self.tree[i][::] = [self.nown[b]]
        else:
            m = (b + e) >> 1
            self._build(2 * i, b, m)
            self._build(2 * i + 1, m + 1, e)
            self.tree[i] = self.tree[2 * i] + self.tree[2 * i + 1]

    def _set(self, i, x, a, b):
        st = 0
        while a < b:
            if b & 1:
                self.tree[i] = self.tree[2 * i] + (b - a + 1)
                a = a + ((a >> 1) + 1)
                if a > self.n:
                    a = self.n
                b = b - (a >> 1)
            else:
                self.tree[i] = self.tree[2 * i] + self.tree[2 * i + 1]
                a = a + ((a >> 1) + 1)
                b = b - (a >> 1)

        self.tree[i][::] = self.tree[i]

    def update(self, a, b, x):
        self._set(1, x + 1, a, b)

    def query(self, l, r):
        ans = 0
        while l < r:
            if r & 1:
                ans = ans + r - l
                if r > self.n - self.nown[l - 1]:
                    r = r - ((r >> 1) + 1)
            if l & 1:
                ans = ans + l
                if r > self.n - self.nown[l + 1]:
                    l = l + ((l >> 1) + 1)
            l = l + ((l >> 1) + 1)
            r = r - ((r >> 1) + 1)
        return ans + self.nown[r]

class Solution:
    def optimalSummands(self, n: int, m: int, q: int) -> List[int]:
        a = [0] + sorted([-x for x in range(n)])
        b = [0] + sorted([-x for x in range(m)])
        mx = max(n, m)
        w = 2 * mx
        mod = 10**9 + 7
        solution = SegmentTree(2 * mx + 1)  # Using 2*mx elements, some spaces will be filled by inf

        for b_0 in sorted(acq(a)):
            solution.update(0, 2 * w + 1, b_0)

        for b_1 in sorted(acq(b)):
            solution.update(b_1, 2 * mx + 1, b_0)

        ans = []
        for _ in range(q):
            t = list(map(int, input().split()))
            tc = t[0]
            l = t[1]
            r = t[2]
            if tc == 1:
                solution.update(l, r, t[3])
            elif tc == 2:
                solution.update(0, 2 * w + 2, l)
            elif tc == 3:
                ans.append(solution.query(0, 2 * mx + 1))
            else:
                w -= 1

        return ans
