def max_flow(n, t, walls):
    def preprocess(wall):
        left, right = wall[1], wall[2]
        # Handle the boundary conditions
        if left <= -10**9:
            left += t
        if right >= 10**9:
            right += t
        return (-t + left, t - right)

    for wall in walls:
        walls[walls.index(wall)] = preprocess(wall)

    max_flow = 0
    for wall in walls:
        i = t - wall[0]
        while len(walls) > i:
            wall_to_check = walls.pop(i)
            if wall_to_check[0] < wall[0]:
                if wall_to_check[1] > wall[1]:
                    max_flow = max(max_flow, wall_to_check[1] - wall[1])
                else:
                    max_flow = max(max_flow, wall[1] - wall_to_check[1])

    return max_flow

